firmware:
#include <Wire.h>
#include <LiquidCrystal_I2C.h>
#include <DHT.h>

const int DHT_PIN = 15;
const int SDA_PIN = 21;
const int SCL_PIN = 22;
const uint8_t LCD_ADDR = 0x27;
DHT dht(DHT_PIN, DHT22);
LiquidCrystal_I2C lcd(LCD_ADDR, 16, 2);
bool lcdOk = false;

void setup() {
  Serial.begin(115200);
  dht.begin();
  Wire.begin(SDA_PIN, SCL_PIN);
  Wire.setTimeOut(50);
  Wire.beginTransmission(LCD_ADDR);
  if (Wire.endTransmission() != 0) {
    Serial.println("NO_LCD");
    return;
  }
  lcd.init();
  lcd.backlight();
  lcdOk = true;
}

void loop() {
  delay(2000);
  if (!lcdOk) {
    return;
  }
  float t = dht.readTemperature();
  if (isnan(t)) {
    return;
  }
  lcd.setCursor(0, 0);
  lcd.print("Temp: ");
  lcd.print(t, 1);
  lcd.print(" C  ");
  Serial.print("TEMP=");
  Serial.println(t);
}
